    @MainActor private static var cache: [SolarSymbol: NSImage] = [:]

    @MainActor var image: NSImage {
        if let cached = Self.cache[self] { return cached }
        let img = NSImage(data: Data(svg.utf8)) ?? NSImage()
        img.isTemplate = true
        Self.cache[self] = img
        return img
    }
}

/// Substituto de `Image(systemName:)` usando Solar. `size` é o lado em pontos.
struct SolarIcon: View {
    let symbol: SolarSymbol
    var size: CGFloat = 14

    init(_ symbol: SolarSymbol, size: CGFloat = 14) {
        self.symbol = symbol
        self.size = size
    }

    var body: some View {
        Image(nsImage: symbol.image)
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .frame(width: size, height: size)
    }
}
